import React, { createElement, useState } from "react";
import * as prod from "react/jsx-runtime";
import rehypeReact, { Components, Options } from "rehype-react";
import rehypeParse from "rehype-parse";
import { unified } from "unified";
import { Node } from "unist";

import loadable from '@loadable/component';

// We need this to ensure we don't precompile FSImage!
const FSImage = loadable(() => import('./FSImage'));

interface HtmlAstRendererProps {
    htmlAst: Node; // Use the appropriate type for your AST structure
}

const HtmlAstRenderer: React.FC<HtmlAstRendererProps> = ({ htmlAst }) => {

    // Define the production options for `rehype-react`
    // @ts-expect-error: the react types are missing.
    const options: Options = {
        Fragment: prod.Fragment,
        components: {
            fsimage: FSImage,
        },
        jsx: prod.jsx,
        jsxs: prod.jsxs,
    };

    // Process the htmlAst when the component mounts
    // This is a self-invoking async function
    const content = unified()
        .use(rehypeParse, {
            fragment: true,
        }) // Assuming htmlAst is a fragment
        .use(rehypeReact, options)
        .stringify(htmlAst);

    return content;
};

export default HtmlAstRenderer;
